308	    /**
309	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
310	     * {@code registrationDate} on a fiscal year that starts on 1 July, formatted {@code 'FY<YY>'}
311	     * where YY is the last two digits of the fiscal year, zero-padded (e.g. a registration date of
312	     * 2026-08-16 yields {@code 'FY27'}).
313	     *
314	     * @return the fiscal year, or {@code null} when no {@code registrationDate} is set
315	     */
316	    @Transient
317	    public String getFiscalYear() {
318	        if (this.registrationDate == null) {
319	            return null;
320	        }
321	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
322	    }
323	
324	    /**
325	     * The owner's membership points, derived on read from the fields assigned at create. Points
326	     * start at 0 and accumulate: 2 when an email is present, 1 when {@code namesakeCount} is 0,
327	     * 2 when the household has 3 or more members ({@code householdMemberCount} of 3 or more), and
328	     * 3 when the owner's tenure spans at least one elapsed fiscal year. Tenure is the number of
329	     * fiscal years (which start on 1 July) elapsed between the {@code registrationDate} and the
330	     * current date. Because a newly created owner has zero tenure, the tenure points are only
331	     * earned once the owner has entered a later fiscal year than the one they registered in.
332	     *
333	     * @return the membership points, 0 or more
334	     */
335	    @Transient
336	    public Integer getMembershipPoints() {
337	        int points = 0;
338	        if (this.email != null && !this.email.isBlank()) {
339	            points += 2;
340	        }
341	        if (this.namesakeCount != null && this.namesakeCount == 0) {
342	            points += 1;
343	        }
344	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
345	            points += 2;
346	        }
347	        if (this.registrationDate != null
348	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
349	            points += 3;
350	        }
351	        return points;
352	    }
353	
354	    /**
355	     * The owner's numeric membership level, derived on read by mapping {@link #getMembershipPoints}
356	     * to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
357	     * Because a newly created owner has zero tenure, level 4 (which requires the tenure points) is
358	     * reached only once the owner has entered a later fiscal year than the one they registered in.
359	     *
360	     * <p>The points-derived level is finally capped by {@link #membershipLevelCap} when one was
361	     * assigned at create: a new owner joining an existing household without declaring it (see
362	     * {@code membershipLevelCap}) may not exceed one above the highest membership level already held
363	     * by an existing household member, so the returned level is the lesser of the derived level and
364	     * the cap. When no cap was assigned (a household's first member, or a declared member) the
365	     * derived level is returned unchanged.
366	     *
367	     * @return the membership level, from 1 to 4
368	     */
369	    @Transient
370	    public Integer getMembershipLevel() {
371	        int points = getMembershipPoints();
372	        int level;
373	        if (points >= 6) {
374	            level = 4;
375	        }
376	        else if (points >= 4) {
377	            level = 3;
378	        }
379	        else if (points >= 2) {
380	            level = 2;
381	        }
382	        else {
383	            level = 1;
384	        }
385	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
386	            return this.membershipLevelCap;
387	        }
388	        return level;
389	    }
390	
391	    /**
392	     * The owner's preferred contact channel, derived on read: {@code 'EMAIL'} when an
393	     * email address is present, otherwise {@code 'PHONE'}.
394	     *
395	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
396	     */
397	    @Transient
398	    public String getContactPreference() {
399	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
400	    }
401	
402	    /**
403	     * The owner's age band, derived on read from {@code birthDate} against the
404	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18, {@code 'ADULT'}
405	     * from 18 to 64, and {@code 'SENIOR'} at 65 or older. The age is the number of whole years
406	     * between the birth date and the registration date (falling back to the current date when no
407	     * registration date is set).
408	     *
409	     * @return the age band, or {@code null} when no {@code birthDate} is set
410	     */
411	    @Transient
412	    public String getAgeBand() {
413	        if (this.birthDate == null) {
414	            return null;
415	        }
416	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
417	        int age = Period.between(this.birthDate, reference).getYears();
418	        if (age < 18) {
419	            return "MINOR";
420	        }
421	        if (age < 65) {
422	            return "ADULT";
423	        }
424	        return "SENIOR";
425	    }
426	
427	    /**
428	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
429	     * digits contained in the owner's {@code customerCode}.
430	     *
431	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
432	     */
433	    @Transient
434	    public Integer getCheckDigit() {
435	        if (this.customerCode == null) {
436	            return null;
437	        }
438	        int sum = 0;
439	        boolean dbl = true;
440	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
441	            char c = this.customerCode.charAt(i);
442	            if (c < '0' || c > '9') {
443	                continue;
444	            }
445	            int d = c - '0';
446	            if (dbl) {
447	                d *= 2;
448	                if (d > 9) {
449	                    d -= 9;
450	                }
451	            }
452	            sum += d;
453	            dbl = !dbl;
454	        }
455	        return (10 - (sum % 10)) % 10;
456	    }
457	
458	    /**
459	     * The owner's stored E.164 {@code telephone} formatted for humans, derived on read: the
460	     * leading {@code '+'} and country code, a space, then the national digits grouped in threes
461	     * (e.g. {@code '+61 412 345 678'} for a stored {@code '+61412345678'}). The recognised
462	     * country codes are {@code '+61'} (Australia) and {@code '+1'} (NANP); any other prefix falls
463	     * back to a two-digit country code. The raw {@code telephone} is left in E.164 form.
464	     *
465	     * @return the human-formatted telephone, or the raw value when it is not in E.164 form
466	     */
467	    @Transient
468	    public String getTelephoneDisplay() {
469	        if (this.telephone == null || !this.telephone.startsWith("+")
470	                || !this.telephone.substring(1).matches("[0-9]+")) {
471	            return this.telephone;
472	        }
473	        String digits = this.telephone.substring(1);
474	        String countryCode;
475	        if (digits.startsWith("61")) {
476	            countryCode = "61";
477	        } else if (digits.startsWith("1")) {
478	            countryCode = "1";
479	        } else {
480	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
481	        }
482	        String national = digits.substring(countryCode.length());
483	        StringBuilder display = new StringBuilder("+").append(countryCode);
484	        for (int i = 0; i < national.length(); i += 3) {
485	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
486	        }
487	        return display.toString();
488	    }
489	
490	    /**
491	     * The owner's derived duplicate-detection key: the single consolidated identity used to
492	     * detect duplicate owners on create. It is the lower-case hex SHA-256 digest of
493	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} from the owner's
494	     * already-normalized {@code telephone} (E.164 form), its lower-cased {@code email} (empty
495	     * when absent) and the Soundex code of its {@code lastName} (see {@link #soundex}). Two owners
496	     * are duplicates only when their whole {@code identityKey} values are equal.
497	     *
498	     * @return the consolidated identity key
499	     */
500	    @Transient
501	    public String getIdentityKey() {
502	        return identityKey(this.telephone, this.email, this.lastName);
503	    }
504	
505	    /**
506	     * Computes the consolidated {@code identityKey} for the given identity-bearing fields: the
507	     * lower-case hex SHA-256 digest of
508	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The {@code email}
509	     * is lower-cased (empty when absent) and the {@code lastName} is reduced to its Soundex code
510	     * (see {@link #soundex}). The {@code telephone} is expected already normalized to E.164 form.
511	     *
512	     * @param telephone the owner's normalized (E.164) telephone, possibly {@code null}
513	     * @param email     the owner's email, possibly {@code null}
514	     * @param lastName  the owner's last name, possibly {@code null}
515	     * @return the lower-case hex SHA-256 identity key
516	     */
517	    public static String identityKey(String telephone, String email, String lastName) {
518	        String telephonePart = telephone == null ? "" : telephone;
519	        String emailPart = email == null ? "" : email.toLowerCase(Locale.ROOT);
520	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundex(lastName));
521	    }
522	
523	    /**
524	     * Returns the American Soundex code of {@code value}: the first letter followed by three
525	     * digits encoding the remaining consonants (b,f,p,v→1; c,g,j,k,q,s,x,z→2; d,t→3; l→4; m,n→5;
526	     * r→6), where vowels and {@code h}/{@code w} are not coded, adjacent letters with the same
527	     * code collapse to one (and a code repeated across an {@code h}/{@code w} is treated as
528	     * adjacent), and the result is right-padded with zeros to length four. A {@code null} or
529	     * letter-free value yields the empty string.
530	     *
531	     * @param value the value to encode, possibly {@code null}
532	     * @return the four-character Soundex code, or the empty string when there is no letter
533	     */
534	    public static String soundex(String value) {
535	        if (value == null) {
536	            return "";
537	        }
538	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
539	        if (letters.isEmpty()) {
540	            return "";
541	        }
542	        StringBuilder code = new StringBuilder();
543	        code.append(letters.charAt(0));
544	        char previous = soundexDigit(letters.charAt(0));
545	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
546	            char c = letters.charAt(i);
547	            if (c == 'H' || c == 'W') {
548	                continue;
549	            }
550	            char digit = soundexDigit(c);
551	            if (digit != '0' && digit != previous) {
552	                code.append(digit);
553	            }
554	            previous = (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y')
555	                ? '0' : digit;
556	        }
557	        while (code.length() < 4) {
558	            code.append('0');
559	        }
560	        return code.toString();
561	    }
562	
563	    private static char soundexDigit(char c) {
564	        switch (c) {
565	            case 'B': case 'F': case 'P': case 'V':
566	                return '1';
567	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
568	                return '2';
569	            case 'D': case 'T':
570	                return '3';
571	            case 'L':
572	                return '4';
573	            case 'M': case 'N':
574	                return '5';
575	            case 'R':
576	                return '6';
577	            default:
578	                return '0';
579	        }
580	    }
581	
582	    private static String sha256Hex(String value) {
583	        try {
584	            byte[] digest = MessageDigest.getInstance("SHA-256")
585	                .digest(value.getBytes(StandardCharsets.UTF_8));
586	            StringBuilder sb = new StringBuilder(digest.length * 2);
587	            for (byte b : digest) {
588	                sb.append(String.format("%02x", b));
589	            }
590	            return sb.toString();
591	        }
592	        catch (NoSuchAlgorithmException e) {
593	            throw new IllegalStateException("SHA-256 not available", e);
594	        }
595	    }
596	
597	    /**
598	     * A link to this owner's own resource, derived on read as {@code '/api/owners/'} followed by
599	     * the owner's id.
600	     *
601	     * @return the self link, or {@code null} when no id is assigned
602	     */
603	    @Transient
604	    public String getSelfLink() {
605	        return getId() == null ? null : "/api/owners/" + getId();
606	    }
607	
608	    protected Set<Pet> getPetsInternal() {
609	        if (this.pets == null) {
610	            this.pets = new HashSet<>();
611	        }
612	        return this.pets;
613	    }
614	
615	    protected void setPetsInternal(Set<Pet> pets) {
616	        this.pets = pets;
617	    }
618	
619	    public List<Pet> getPets() {
620	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
621	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
622	        return Collections.unmodifiableList(sortedPets);
623	    }
624	
625	    public void setPets(List<Pet> pets) {
626	        this.pets = new HashSet<>(pets);
627	    }
628	
629	    public void addPet(Pet pet) {
630	        getPetsInternal().add(pet);
631	        pet.setOwner(this);
632	    }
633	
634	    /**
635	     * Return the Pet with the given name, or null if none found for this Owner.
636	     *
637	     * @param name to test
638	     * @return true if pet name is already in use
639	     */
640	    public Pet getPet(String name) {
641	        return getPet(name, false);
642	    }
643	
644	    /**
645	     * Return the Pet with the given name, or null if none found for this Owner.
646	     *
647	     * @param name to test
648	     * @return true if pet name is already in use
649	     */
650	    public Pet getPet(String name, boolean ignoreNew) {
651	        name = name.toLowerCase();
652	        for (Pet pet : getPetsInternal()) {
653	            if (!ignoreNew || !pet.isNew()) {
654	                String compName = pet.getName();
655	                compName = compName.toLowerCase();
656	                if (compName.equals(name)) {
657	                    return pet;
658	                }
659	            }
660	        }
661	        return null;
662	    }
663	
664	    public Pet getPet(Integer petId) {
665	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
666	    }
667	
668	    @Override
669	    public String toString() {
670	        return new ToStringCreator(this)
671	
672	            .append("id", this.getId())
673	            .append("new", this.isNew())
674	            .append("lastName", this.getLastName())
675	            .append("firstName", this.getFirstName())
676	            .append("address", this.address)
677	            .append("city", this.city)
678	            .append("telephone", this.telephone)
679	            .append("email", this.email)
680	            .toString();
681	    }
682	}
